def solve(i):
    h,w=len(i),len(i[0]); o=[row[:] for row in i]
    cnt={}
    for r in range(h):
        for c in range(w): cnt[i[r][c]]=cnt.get(i[r][c],0)+1
    bg=max(cnt,key=lambda k:cnt[k])
    vals={k:v for k,v in cnt.items() if k!=bg}
    def isolated(k):
        cells=[(r,c) for r in range(h) for c in range(w) if i[r][c]==k]
        return all((r==0 or i[r-1][c]!=k) and (r==h-1 or i[r+1][c]!=k) and (c==0 or i[r][c-1]!=k) and (c==w-1 or i[r][c+1]!=k) for r,c in cells)
    dotcol=[k for k in vals if isolated(k)]
    line=[k for k in vals if k not in dotcol]
    dots=[(r,c) for r in range(h) for c in range(w) if i[r][c] in dotcol]
    barcells=set((r,c) for r in range(h) for c in range(w) if i[r][c] in line)
    seen=set(); bars=[]
    for cell in barcells:
        if cell in seen: continue
        stack=[cell]; comp=set()
        while stack:
            a,b=stack.pop()
            if (a,b) in seen: continue
            seen.add((a,b)); comp.add((a,b))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                na,nb=a+dr,b+dc
                if 0<=na<h and 0<=nb<w and (na,nb) not in seen and (na,nb) in barcells:
                    stack.append((na,nb))
        bars.append(sorted(comp))
    dotrows={r for r,c in dots}
    # barA: the bar whose row-span intersects the dots' rows (or is otherwise aligned); pick bar containing the smallest dot row? demos used top-left-most matching
    # safer: barA = bar whose row-range overlaps dot rows; fall back leftmost top
    A=None
    for b in bars:
        if min(r for r,c in b)<=min(dotrows)<=max(r for r,c in b): A=b
    B=[b for b in bars if b is not A][0]
    topA=min(r for r,c in A); topB=min(r for r,c in B)
    acol={c for r,c in A}; last=w-1
    dotcolv=i[dots[0][0]][dots[0][1]]
    for (dr,dc) in dots:
        d=(dr,dc)
        step=1 if dc<min(acol) else -1
        cc=dc
        while True:
            cc+=step
            if not(0<=cc<w): break
            if (dr,cc) in barcells: break
            o[dr][cc]=dotcolv
    for (dr,dc) in dots:
        o[dr][dc]=4
        off=dr-topA
        br=topB+off
        if 0<=br<h:
            cc=1
            while cc<=last:
                if (br,cc) in barcells: break
                o[br][cc]=dotcolv
                cc+=1
    return o
